function integrationsPage(){return page('Everything, connected.','Configure adapters and inspect delivery behavior without sending data.',B('＋ Add adapter','adapter-new','',true))+tabs([['adapters','Connections'],['outbox','Outbound events'],['inbound','Inbound simulator']])+(tabIs('adapters','adapters')?`<div class="cards">${db().adapters.map(a=>`<section class="panel padded"><div class="section-heading"><h2>${e(a.name)}</h2>${tag(a.active?'Active':'Paused')}</div><p class="subtitle">${e(a.kind)}</p><p class="code-line">${e(a.url)}</p><div class="metric-row">Delivery simulator<strong>${a.failure?'503 failure':'200 success'}</strong></div><p class="secondary">${a.events.map(e).join(', ')}</p><div class="row-actions">${B('Configure','adapter-edit',a.id)}${B('Send test','adapter-test',a.id)}${B(a.active?'Pause':'Activate','adapter-toggle',a.id)}</div></section>`).join('')}</div>`:tabIs('outbox','adapters')?panel('Delivery logs & retries',table(['EVENT','ADAPTER','STATUS','ATTEMPTS','RESPONSE',''],db().outbox.slice(0,40).map(x=>[e(x.type),e(E.find('adapters',x.adapter).name),tag(x.status),x.attempts,e(x.response),`${B('Payload','event-payload',x.id)} ${x.status==='Failed'?B('Retry','event-retry',x.id):''}`]))):panel('Replay a partner award',form('inbound',`<div class="form-grid">${select('Member','customer',cOptions(),U.selected)}${input('Points','points',100,'number','min="1" max="1000" required')}${input('Unique event reference','reference','partner-'+(db().seq+1),'text','required')}</div>`+notice('Replaying the same reference is rejected to prevent duplicate awards.'),'Process local event')))+notice('No network requests are made. Production adapters require API credentials, provider contracts, and server-side delivery workers.')}
function dataPage(){return page('Your data, on your terms.','Field-level exports, local schedules, and portable workspace backups.',B('Download backup','backup')+B('Restore backup','restore'))+tabs([['export','Export builder'],['schedules','Scheduled exports'],['history','Export history']])+(tabIs('export','export')?panel('Build a CSV export',form('export',select('Dataset','dataset',[['customers','Customers'],['transactions','Transactions'],['campaigns','Campaigns'],['offers','Offers'],['coupons','Coupon codes'],['orders','Merchandise orders'],['audit','Audit trail']],U.dataset||'transactions','id="export-dataset"')+`<div id="export-fields" class="field-checks">${exportFields(U.dataset||'transactions')}</div>`+check('Save as recurring export','recurring',false)+`<div class="form-grid">${input('Schedule name','name','Weekly performance')}${select('Cadence','cadence',[[1,'Daily'],[7,'Weekly'],[30,'Monthly']],7)}</div>`,'Download CSV')):tabIs('schedules','export')?panel('Local export schedules',table(['SCHEDULE','DATASET','CADENCE','NEXT RUN',''],db().exportJobs.map(j=>[e(j.name),j.dataset,j.cadence+' days',date(j.next),B(j.active?'Pause':'Activate','export-toggle',j.id)])),B('Run due jobs','clock')):panel('Prepared reports',table(['REPORT','DATASET','ROWS','CREATED',''],db().exportHistory.map(h=>[e(h.job),h.dataset,h.rows,time(h.date),B('Download','export-history',h.id)]))))}
