function teamPage(){return page('The right access for every team.','Configure permissions and preview how each role experiences Ember.',B('＋ Add team member','team-new','',true))+tabs([['users','Team members'],['roles','Roles & scope']])+(tabIs('users','users')?panel('Workspace team',table(['NAME','EMAIL','ROLE','STATUS'],db().team.map(u=>[e(u.name),e(u.email),e(db().roles.find(r=>r.id===u.role)?.name||u.role),tag(u.status)]))):panel('Role permissions',table(['ROLE','PERMISSIONS','STORES','GIFT LIMIT','EXPORT',''],db().roles.map(r=>[e(r.name),r.permissions.length+' areas',r.stores.length?r.stores.map(id=>E.find('stores',id).name).join(', '):'All stores',r.giftLimit+' pts',r.export?'Allowed':'Blocked',r.id==='owner'?'Owner role':B('Edit','role-edit',r.id)])),B('Create role','role-new')))+notice('The role selector in the header is a demo impersonation tool. This local app cannot provide secure authentication or server-enforced access control.')}
function labPage(){return page('Try the idea before you spend.','Explore campaign economics and replay customer moments.')+`<div class="wide-grid">${panel('Campaign contribution forecast',`<form data-form="forecast"><div class="form-grid">${input('Eligible audience','audience',10000,'number','min="1" required')}${input('Conversion rate (%)','conversion',8,'number','min="0" max="100" step="0.1" required')}${input('Average basket (₹)','basket',650,'number','min="1" required')}${input('Gross margin (%)','margin',62,'number','min="0" max="100" required')}${input('Reward cost per order (₹)','reward',100,'number','min="0" required')}${input('Channel cost per message (₹)','messageCost',.25,'number','min="0" step="0.01" required')}</div><button class="primary">Calculate impact</button><p class="form-error"></p></form><div id="forecast-result" class="notice">Enter your assumptions to estimate contribution after reward and messaging costs.</div>`)}${panel('Simulation controls',`<div class="big-number">${date(db().now)}</div><p class="subtitle">Move time forward to process scheduled campaigns, delayed journey steps, renewals, exports, and point expiry.</p><div class="actions wrap" style="margin-top:20px">${B('Advance clock','clock','',true)}${B('Replay event','event-sim')}</div><h3 class="section-title">Latest changes</h3>${db().audit.slice(0,4).map(a=>`<div class="activity"><span>${e(a.action)}</span><small>${time(a.date)}</small></div>`).join('')}`)}</div>`}
